// Compute returns an invoice's totals: the sum of its lines, the discount, and tax at the invoice's rate on the subtotal
// after the discount. The discount is the coupon's when the invoice has one (a percentage of the subtotal, or an amount
// never more than the subtotal), and DiscountPercent of the subtotal otherwise. The discount and the tax are each rounded
// half away from zero to a whole minor unit.
func Compute(inv store.Invoice) Totals {
	var subtotal int64
	for _, l := range inv.Lines {
		subtotal += l.Amount()
	}
	var discount int64
	switch {
	case inv.Coupon != "" && inv.CouponPercentOff > 0:
		discount = money.Percent(subtotal, inv.CouponPercentOff)
	case inv.Coupon != "":
		discount = min(inv.CouponAmountOff, max(subtotal, 0))
	default:
		discount = money.Percent(subtotal, inv.DiscountPercent)
	}
	taxable := subtotal - discount

