func TestComputeWithCoupon(t *testing.T) {
	lines := []store.Line{{Description: "Seats", Quantity: 3, UnitAmount: 999}} // subtotal 2997
	// A coupon replaces the subscription's discount: 10% of 2997 is 299.7, rounded to 300, not 50% of it.
	got := Compute(store.Invoice{Lines: lines, Coupon: "TEN", CouponPercentOff: 10, DiscountPercent: 50})
	if got != (Totals{Subtotal: 2997, Discount: 300, Total: 2697}) {
		t.Fatalf("percent coupon = %+v", got)
	}
	// Tax is charged after the discount: 825 bp of 2997-300.
	got = Compute(store.Invoice{Lines: lines, Coupon: "TAX", CouponPercentOff: 10, TaxRateBP: 825})
	if got.Discount != 300 || got.Tax != 203 || got.Total != 2900 {
		t.Fatalf("taxed = %+v", got)
	}
	got = Compute(store.Invoice{Lines: lines, Coupon: "FIVE", CouponAmountOff: 500})
	if got != (Totals{Subtotal: 2997, Discount: 500, Total: 2497}) {
		t.Fatalf("amount coupon = %+v", got)
	}
	// An amount is never more than the subtotal.
	got = Compute(store.Invoice{Lines: lines, Coupon: "BIG", CouponAmountOff: 99999})
	if got != (Totals{Subtotal: 2997, Discount: 2997}) {
		t.Fatalf("capped coupon = %+v", got)
	}
}

